use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    if let Value::Array(rows) = input {
        let sums = rows
            .into_iter()
            .map(|row| {
                if let Value::Array(ints) = row {
                    ints.into_iter()
                        .map(|v| if let Value::Number(n) = v { n.as_i64().unwrap() } else { 0 })
                        .sum::<i64>()
                } else {
                    0
                }
            })
            .collect();
        Value::Array(sums)
    } else {
        Value::Null
    }
}
